fn saluta(nome: String) {
    println!("Ciao {}", nome);
}

let utente = String::from("Anna");
saluta(utente);
println!("{}", utente);

fn lunghezza(testo: &String) -> usize {
    testo.len()
}

let msg = String::from("errore");
let n = lunghezza(&msg);
println!("{} {}", msg, n);
